-- 최소 엔티티 하나

@Entity
@Getter @Setter
public class Member {
    @Id @GeneratedValue
    private Long id;
    private String username;

    protected Member() {}
    public Member(String username) { this.username = username; }
}


-- 인터페이스 하나

public interface MemberRepository extends JpaRepository<Member, Long> {
}


